-- 0081_formulario_briefing_v2.sql — Briefing padrão mais intuitivo
-- Perguntas com campos separados, listas com "+" (produtos, objeções, concorrentes)
-- e exemplos em todas. Remove "de onde vem o nome". Só atualiza o modelo;
-- formulários já gerados guardam o próprio snapshot e não mudam.

update public.formularios_modelos
set perguntas = $json$[{"id":"nome_empresa","tipo":"texto","label":"Nome da empresa","ajuda":"Ex.: Clínica Sorriso Pleno. Escreva do jeito exato que vai na fachada e nas redes.","obrigatoria":true,"secao":"Empresa e responsáveis"},
{"id":"historia","tipo":"longo","label":"Como começou a história do seu negócio?","ajuda":"Ex.: comecei vendendo para amigos em 2018 e, em 2021, abri a loja porque ninguém na cidade fazia o que eu fazia. Conte o que te levou a começar.","secao":"Empresa e responsáveis"},
{"id":"tempo_mercado","tipo":"texto","label":"Há quanto tempo a empresa está no mercado?","ajuda":"Ex.: 3 anos, desde março de 2023.","secao":"Empresa e responsáveis"},
{"id":"endereco","tipo":"campos","label":"Endereço da empresa","ajuda":"É o endereço que vai aparecer no Google. Se não tem ponto físico, escreva a área que atende no primeiro campo.","obrigatoria":true,"campos":[{"id":"rua","label":"Rua e número","placeholder":"Ex.: Av. Beira Mar, 1200"},
{"id":"bairro","label":"Bairro","placeholder":"Ex.: Centro"},
{"id":"cidade","label":"Cidade/UF","placeholder":"Ex.: Torres/RS"},
{"id":"cep","label":"CEP","placeholder":"Ex.: 95560-000"},
{"id":"ref","label":"Ponto de referência","placeholder":"Ex.: em frente ao mercado X","longo":true}],"secao":"Empresa e responsáveis"},
{"id":"horario","tipo":"campos","label":"Dias e horários de atendimento","ajuda":"Se fecha algum dia, escreva \"fechado\". Se muda na alta temporada, avise no último campo.","campos":[{"id":"semana","label":"Segunda a sexta","placeholder":"Ex.: 9h às 19h"},
{"id":"sabado","label":"Sábado","placeholder":"Ex.: 9h às 13h"},
{"id":"domingo","label":"Domingo e feriados","placeholder":"Ex.: fechado"},
{"id":"obs","label":"Muda em alguma época do ano?","placeholder":"Ex.: no verão abrimos até as 21h","longo":true}],"secao":"Empresa e responsáveis"},
{"id":"whatsapp_leads","tipo":"texto","label":"WhatsApp que vai receber os contatos dos anúncios","ajuda":"Ex.: (51) 99999-9999. É para esse número que os anúncios vão apontar. Diga se já é WhatsApp Business.","obrigatoria":true,"secao":"Empresa e responsáveis"},
{"id":"email_empresa","tipo":"texto","label":"E-mail da empresa","ajuda":"Ex.: contato@suaempresa.com.br","secao":"Empresa e responsáveis"},
{"id":"telefone_fixo","tipo":"texto","label":"Telefone fixo, se houver","ajuda":"Ex.: (51) 3333-3333. Alguns clientes mais velhos ligam em vez de mandar mensagem.","secao":"Empresa e responsáveis"},
{"id":"aprovador","tipo":"campos","label":"Quem aprova as artes e campanhas?","ajuda":"Uma pessoa só, para a aprovação não travar.","obrigatoria":true,"campos":[{"id":"nome","label":"Nome","placeholder":"Ex.: Maria Souza"},
{"id":"zap","label":"WhatsApp","placeholder":"Ex.: (51) 99999-9999"}],"secao":"Empresa e responsáveis"},
{"id":"o_que_faz","tipo":"longo","label":"Resuma em poucas palavras o que a empresa faz","ajuda":"Ex.: somos uma clínica de odontologia estética que faz clareamento e lentes de contato dental em Porto Alegre.","obrigatoria":true,"secao":"Propósito, posicionamento e oferta"},
{"id":"nicho","tipo":"texto","label":"Qual é a área de atuação e o nicho de mercado?","ajuda":"Ex.: odontologia estética para mulheres de 25 a 45 anos.","secao":"Propósito, posicionamento e oferta"},
{"id":"missao","tipo":"longo","label":"Qual é a missão da empresa?","ajuda":"Por que a empresa existe, no dia a dia. Ex.: devolver a confiança de sorrir para quem tinha vergonha do próprio sorriso.","secao":"Propósito, posicionamento e oferta"},
{"id":"visao","tipo":"longo","label":"Qual é a visão da empresa?","ajuda":"Onde quer chegar e em quanto tempo. Ex.: ser a clínica mais lembrada da cidade em estética dental em 3 anos.","secao":"Propósito, posicionamento e oferta"},
{"id":"valores","tipo":"longo","label":"Quais são os valores da empresa?","ajuda":"O que não se negocia no atendimento. Ex.: honestidade, atendimento próximo, qualidade acima do preço, pontualidade.","secao":"Propósito, posicionamento e oferta"},
{"id":"slogan","tipo":"texto","label":"A empresa tem slogan ou frase que a represente?","ajuda":"Ex.: \"Seu melhor sorriso começa aqui\". Se não tiver, escreva \"criar\" e a gente propõe opções.","secao":"Propósito, posicionamento e oferta"},
{"id":"problema_resolve","tipo":"longo","label":"Qual problema o seu produto ou serviço resolve na vida do cliente?","ajuda":"Ex.: gasto alto com combustível; vergonha do próprio sorriso; dificuldade de encontrar mão de obra de confiança.","obrigatoria":true,"secao":"Propósito, posicionamento e oferta"},
{"id":"transformacao","tipo":"longo","label":"Qual é a maior transformação que você entrega ao cliente?","ajuda":"Como a vida dele fica depois de comprar. Ex.: sai mais confiante, economiza por mês, ganha tempo livre.","secao":"Propósito, posicionamento e oferta"},
{"id":"diferencial","tipo":"campos","label":"Quais são os principais diferenciais da empresa em relação à concorrência?","ajuda":"Liste até 3. Ex.: única da cidade com a marca X; atendimento em até 5 minutos; garantia de 1 ano; assistência própria.","obrigatoria":true,"campos":[{"id":"d1","label":"Diferencial 1","placeholder":"Ex.: atendimento em até 5 minutos"},
{"id":"d2","label":"Diferencial 2","placeholder":"Ex.: garantia de 1 ano"},
{"id":"d3","label":"Diferencial 3","placeholder":"Ex.: assistência técnica própria"}],"secao":"Propósito, posicionamento e oferta"},
{"id":"entregas_pos_venda","tipo":"longo","label":"O que a empresa entrega depois que o cliente fecha?","ajuda":"Ex.: instalação, treinamento, suporte por WhatsApp em até 24h, revisão em 30 dias, grupo de clientes.","secao":"Propósito, posicionamento e oferta"},
{"id":"garantia","tipo":"campos","label":"A empresa oferece garantia?","ajuda":"Se não oferece, escreva \"não\" no primeiro campo.","campos":[{"id":"tem","label":"Tem garantia?","placeholder":"Ex.: sim"},
{"id":"prazo","label":"Prazo","placeholder":"Ex.: 12 meses"},
{"id":"cobre","label":"O que a garantia cobre","placeholder":"Ex.: defeito de fabricação, mão de obra","longo":true},
{"id":"nao_cobre","label":"O que a garantia não cobre","placeholder":"Ex.: mau uso, queda, peças de desgaste","longo":true}],"secao":"Propósito, posicionamento e oferta"},
{"id":"como_ser_vista","tipo":"longo","label":"Como você gostaria que a empresa fosse vista nas redes sociais?","ajuda":"Ex.: como referência de confiança; como marca premium e não de preço baixo; como uma empresa próxima e humana.","secao":"Propósito, posicionamento e oferta"},
{"id":"principais_produtos","tipo":"campos","label":"Quais são os principais produtos ou serviços?","ajuda":"Clique em \"+ Adicionar produto\" para cada item. Ex.: Clareamento a laser, R$ 900, margem 60%. Não sabe a margem exata? Coloque um valor aproximado.","obrigatoria":true,"campos":[{"id":"nome","label":"Nome do produto ou serviço","placeholder":"Ex.: Clareamento a laser"},
{"id":"preco","label":"Preço (R$)","placeholder":"Ex.: 900"},
{"id":"margem","label":"Margem de lucro (%)","placeholder":"Ex.: 60%"}],"repetir":true,"rotuloItem":"Produto","secao":"Produtos, serviços e condições comerciais"},
{"id":"produto_destaque","tipo":"longo","label":"Existe algum produto ou serviço que você quer vender com mais força?","ajuda":"Ex.: as lentes de contato dental, porque dão mais lucro e queremos vender mais delas.","secao":"Produtos, serviços e condições comerciais"},
{"id":"formas_pagamento","tipo":"multipla","label":"Formas de pagamento aceitas","ajuda":"Marque todas que a empresa aceita.","opcoes":["Pix","Dinheiro","Débito","Crédito","Boleto","Financiamento","Crediário próprio","Entrada mais parcelas","Outra"],"secao":"Produtos, serviços e condições comerciais"},
{"id":"condicoes_pagamento","tipo":"campos","label":"Condições de pagamento","ajuda":"Se não tem alguma das condições, escreva \"não tem\".","campos":[{"id":"desc","label":"Desconto à vista","placeholder":"Ex.: 5% no Pix"},
{"id":"parc","label":"Parcelamento","placeholder":"Ex.: até 12x sem juros no cartão"},
{"id":"outras","label":"Outras condições","placeholder":"Ex.: entrada de 30% + 6x no boleto","longo":true}],"secao":"Produtos, serviços e condições comerciais"},
{"id":"oferta_atual","tipo":"campos","label":"Existe alguma oferta, promoção ou lançamento previsto?","ajuda":"É o que vai aparecer no anúncio. Se não houver, deixe em branco.","campos":[{"id":"oferta","label":"O que está em oferta","placeholder":"Ex.: Clareamento + limpeza"},
{"id":"preco","label":"Preço ou condição","placeholder":"Ex.: de R$ 1.200 por R$ 890"},
{"id":"validade","label":"Validade","placeholder":"Ex.: até 30/11"},
{"id":"qtd","label":"Quantidade de unidades ou vagas","placeholder":"Ex.: 20 vagas"}],"secao":"Produtos, serviços e condições comerciais"},
{"id":"quem_beneficia","tipo":"campos","label":"Que tipos de pessoas podem ser beneficiadas pelo seu produto ou serviço?","ajuda":"Se atende mais de um tipo de pessoa, clique em \"+ Adicionar tipo de pessoa\". Ex.: Mulheres de 25 a 40 anos, profissionais que aparecem em fotos e vídeos, buscam um sorriso mais bonito.","campos":[{"id":"idade","label":"Idade","placeholder":"Ex.: 25 a 40 anos"},
{"id":"perfil","label":"Característica da pessoa","placeholder":"Ex.: trabalha com atendimento ao público, se preocupa com a aparência"},
{"id":"busca","label":"O que ela procura","placeholder":"Ex.: um sorriso mais bonito, rápido e sem dor","longo":true}],"repetir":true,"rotuloItem":"Tipo de pessoa","secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"quem_mais_precisa","tipo":"longo","label":"Quem são as pessoas que MAIS precisam do seu produto ou serviço?","ajuda":"Pense em quem resolveria um problema real comprando. Ex.: quem tem vergonha de sorrir em fotos; quem vai casar e quer o sorriso ideal; quem já tentou outros tratamentos sem resultado.","obrigatoria":true,"secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"publico_principal","tipo":"campos","label":"Quem é o público-alvo principal?","ajuda":"Descreva o cliente que mais compra de você hoje (ou o que você quer atrair).","obrigatoria":true,"campos":[{"id":"idade","label":"Faixa de idade","placeholder":"Ex.: 30 a 45 anos"},
{"id":"onde","label":"Onde mora","placeholder":"Ex.: Porto Alegre e região metropolitana"},
{"id":"prof","label":"Profissão e faixa de renda","placeholder":"Ex.: profissionais liberais, renda de R$ 5 a 10 mil"},
{"id":"escol","label":"Escolaridade","placeholder":"Ex.: ensino superior"},
{"id":"estilo","label":"Estilo de vida e interesses","placeholder":"Ex.: academia, viagens, cuida da aparência, usa muito Instagram","longo":true}],"secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"genero","tipo":"escolha","label":"Gênero predominante do cliente ideal","ajuda":"Escolha o que mais se aproxima. Isso ajuda a escolher imagens e linguagem.","opcoes":["Mais homens","Mais mulheres","Equilibrado","Não sei ainda"],"secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"estado_civil","tipo":"escolha","label":"Status de relacionamento mais comum","ajuda":"Escolha o que mais se aproxima.","opcoes":["Casado(a)","Solteiro(a)","Divorciado(a)","Viúvo(a)","Variado"],"secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"publico_especifico","tipo":"longo","label":"Existe algum público específico que você gostaria de atingir?","ajuda":"Ex.: gestantes, noivas, empresários, aposentados, moradores de um bairro específico.","secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"habitos","tipo":"longo","label":"O que essas pessoas costumam fazer no dia a dia?","ajuda":"Rotina, hábitos de compra e consumo. Ex.: acordam cedo, usam Instagram à noite, pesquisam no Google antes de comprar, pedem indicação a amigos.","secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"o_que_falam","tipo":"longo","label":"O que essas pessoas costumam falar sobre seus problemas e desejos?","ajuda":"Escreva frases do jeito que elas falam. Ex.: \"Não aguento mais gastar tanto com gasolina\", \"Tenho vergonha de tirar foto\".","secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"o_que_pensam","tipo":"longo","label":"O que elas costumam pensar?","ajuda":"Crenças, medos e preocupações. Ex.: \"serviço barato é de má qualidade\", \"tenho medo de ser enganado\".","secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"o_que_escutam","tipo":"longo","label":"O que elas costumam escutar e quem influencia a decisão?","ajuda":"Ex.: opinião da esposa, indicação de amigo, influenciador da região, o que o médico recomenda.","secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"desejos","tipo":"campos","label":"O que essas pessoas desejam?","ajuda":"Pense na vida pessoal e profissional delas.","campos":[{"id":"quer","label":"O que querem conquistar","placeholder":"Ex.: mais autoestima, economizar dinheiro, ter mais tempo livre","longo":true},
{"id":"motiva","label":"O que as motiva a comprar","placeholder":"Ex.: ver o resultado de outra pessoa, uma data especial, uma promoção","longo":true}],"secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"dores","tipo":"campos","label":"Quais são as maiores dores, frustrações e problemas dessas pessoas?","ajuda":"Quanto mais honesto e específico, melhor o anúncio.","obrigatoria":true,"campos":[{"id":"dor","label":"Maior dor ou problema do dia a dia","placeholder":"Ex.: gasta muito e não vê resultado","longo":true},
{"id":"frustracao","label":"Maior frustração com o que já tentaram antes","placeholder":"Ex.: contrataram outra empresa e foram mal atendidos","longo":true},
{"id":"medo","label":"Maior medo ao comprar","placeholder":"Ex.: ser enganado, pagar caro e se arrepender","longo":true}],"secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"habilidades_dificuldades","tipo":"campos","label":"Quais são as principais habilidades e dificuldades dessas pessoas?","ajuda":"Ex.: sabe usar o celular, mas tem dificuldade para entender termos técnicos.","campos":[{"id":"sabe","label":"O que fazem bem","placeholder":"Ex.: usam bem o WhatsApp e o Instagram"},
{"id":"dificuldade","label":"Onde têm dificuldade","placeholder":"Ex.: não entendem termos técnicos"}],"secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"valorizam","tipo":"multipla","label":"O que essas pessoas mais valorizam ao comprar?","ajuda":"Marque até 4.","opcoes":["Qualidade","Preço justo","Praticidade","Confiança","Atendimento","Status","Rapidez","Garantia","Indicação de quem conhece","Outro"],"secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"beneficios_esperados","tipo":"longo","label":"Que benefícios elas esperam receber ao comprar?","ajuda":"Pense em ganhos e resultados, não só no produto. Ex.: resultado rápido, mais segurança, economia, mais tempo livre.","secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"objecoes","tipo":"campos","label":"Que objeções você já ouviu de clientes?","ajuda":"São as desculpas ou dúvidas na hora de fechar. Clique em \"+ Adicionar objeção\" para cada uma. Ex.: \"Está caro\" / \"Mostro o que está incluso e parcelo\".","obrigatoria":true,"campos":[{"id":"obj","label":"O que o cliente diz","placeholder":"Ex.: está caro"},
{"id":"resp","label":"Como você costuma responder","placeholder":"Ex.: mostro tudo o que está incluso e ofereço parcelamento","longo":true}],"repetir":true,"rotuloItem":"Objeção","secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"quem_decide","tipo":"escolha","label":"Quem decide e quem paga a compra?","ajuda":"Escolha o que acontece na maioria das vendas.","opcoes":["O próprio cliente decide e paga","Decide junto com cônjuge ou família","Outra pessoa decide ou paga (filhos, empresa)","Depende do produto"],"secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"redes_persona","tipo":"multipla","label":"Quais redes sociais essas pessoas mais usam?","ajuda":"Marque todas que se aplicam.","opcoes":["Instagram","Facebook","TikTok","YouTube","WhatsApp","LinkedIn","Google","Outras"],"secao":"Público-alvo, persona e cliente ideal (ICP)"},
{"id":"concorrentes","tipo":"campos","label":"Quais empresas disputam o mesmo cliente que você?","ajuda":"Clique em \"+ Adicionar concorrente\" para cada um. Se você testou o atendimento deles, conte o que percebeu.","obrigatoria":true,"campos":[{"id":"nome","label":"Nome da empresa","placeholder":"Ex.: Clínica Dente Bom"},
{"id":"onde","label":"Instagram ou site, e cidade","placeholder":"Ex.: @dentebom, Porto Alegre"},
{"id":"bem","label":"O que ele faz bem","placeholder":"Ex.: preço baixo, aparece muito no Instagram","longo":true},
{"id":"mal","label":"Onde ele deixa a desejar","placeholder":"Ex.: demora para responder, não faz pós-venda","longo":true}],"repetir":true,"rotuloItem":"Concorrente","secao":"Concorrência e referências"},
{"id":"referencias","tipo":"campos","label":"Quais perfis ou marcas você admira e usa como referência?","ajuda":"Podem ser da sua área ou de qualquer outro ramo. Clique em \"+ Adicionar referência\" para cada um.","campos":[{"id":"perfil","label":"Perfil ou marca","placeholder":"Ex.: @nubank"},
{"id":"ramo","label":"Ramo","placeholder":"Ex.: banco digital"},
{"id":"gosta","label":"O que você gosta no jeito deles","placeholder":"Ex.: linguagem simples e visual limpo","longo":true}],"repetir":true,"rotuloItem":"Referência","secao":"Concorrência e referências"},
{"id":"nao_fazer","tipo":"multipla","label":"O que a marca NÃO quer fazer na comunicação?","ajuda":"Marque tudo o que a empresa quer evitar.","opcoes":["Brigar por preço","Falar mal do concorrente","Usar meme ou humor fora de contexto","Prometer resultado garantido","Anúncio poluído com preço gritado","Linguagem muito formal","Outro"],"secao":"Concorrência e referências"},
{"id":"nao_fazer_obs","tipo":"texto","label":"Mais alguma coisa que a marca não quer fazer?","ajuda":"Ex.: nunca usar fotos de banco de imagem; não citar o nome de concorrentes.","secao":"Concorrência e referências"},
{"id":"logo_status","tipo":"escolha","label":"Situação do logo","ajuda":"Se tiver um rascunho, mande no grupo: serve de ponto de partida.","opcoes":["Já possuo logo e identidade pronta","Existe um rascunho","Em produção com outra pessoa","Não existe, criar do zero"],"secao":"Identidade visual"},
{"id":"logo_tipo","tipo":"escolha","label":"Que tipo de logo você imagina?","ajuda":"Só responda se vamos criar o logo. O símbolo que funciona sozinho vira foto de perfil e adesivo.","opcoes":["Só o nome escrito","Nome com um símbolo ao lado","Símbolo que funcione sozinho","Monograma com as iniciais","Não tenho preferência"],"secao":"Identidade visual"},
{"id":"cores","tipo":"campos","label":"Cores da marca","ajuda":"Não precisa saber nomes técnicos. Ex.: \"azul do mar\", \"preto com dourado\".","campos":[{"id":"principal","label":"Cor principal","placeholder":"Ex.: azul-marinho"},
{"id":"apoio","label":"Cores de apoio","placeholder":"Ex.: branco e cinza claro"},
{"id":"evitar","label":"Cores que NÃO quer de jeito nenhum","placeholder":"Ex.: rosa, e nada que lembre um concorrente"}],"secao":"Identidade visual"},
{"id":"estilo_visual","tipo":"multipla","label":"Estilo visual que combina com a marca","ajuda":"Marque até 3.","opcoes":["Minimalista e limpo","Premium e sofisticado","Esportivo e cheio de energia","Tecnológico e futurista","Clássico e elegante","Descontraído e leve","Robusto e durável","Acolhedor e humano","Outro"],"secao":"Identidade visual"},
{"id":"estilo_descricao","tipo":"longo","label":"Quer descrever o estilo com as suas palavras?","ajuda":"Ex.: parecer uma loja da Apple; parecer um consultório de luxo; parecer uma marca jovem e divertida.","secao":"Identidade visual"},
{"id":"marcas_admira","tipo":"campos","label":"Marcas, de qualquer ramo, cuja identidade visual você admira","ajuda":"Clique em \"+ Adicionar marca\" para cada uma.","campos":[{"id":"marca","label":"Marca","placeholder":"Ex.: Apple"},
{"id":"gosta","label":"O que te agrada nela","placeholder":"Ex.: cores neutras, muito espaço em branco","longo":true}],"repetir":true,"rotuloItem":"Marca","secao":"Identidade visual"},
{"id":"marcas_nao_parecer","tipo":"longo","label":"Marcas ou visuais que a empresa NÃO pode parecer","ajuda":"Ex.: loja com banner amarelo de promoção; anúncio poluído de concessionária popular.","secao":"Identidade visual"},
{"id":"tipografia","tipo":"escolha","label":"Preferência de letra","ajuda":"É o que define a cara do nome nos anúncios.","opcoes":["Reta e moderna","Com serifa, mais clássica","Forte e condensada","Não tenho preferência"],"secao":"Identidade visual"},
