{"id":"fb","label":"Facebook","placeholder":"Ex.: facebook.com/suaempresa"},
{"id":"tt","label":"TikTok","placeholder":"Ex.: @suaempresa"},
{"id":"yt","label":"YouTube","placeholder":"Ex.: youtube.com/@suaempresa"},
{"id":"gmn","label":"Google Meu Negócio","placeholder":"Ex.: já tenho, link do perfil"}],"secao":"Redes sociais, conteúdo e tom de voz"},
