{"id":"objetivo_redes","tipo":"multipla","label":"Qual é o principal objetivo da empresa nas redes sociais?","ajuda":"Marque até 3.","obrigatoria":true,"opcoes":["Aumentar as vendas","Fortalecer a marca","Gerar engajamento","Captar novos clientes","Ser encontrada por quem pesquisa","Outro"],"secao":"Redes sociais, conteúdo e tom de voz"},
{"id":"metas","tipo":"campos","label":"Metas que você quer alcançar","ajuda":"Deixe em branco o que não for meta. Ex.: 3 mil seguidores, 100 mensagens por mês, 15 vendas por mês.","campos":[{"id":"seg","label":"Seguidores","placeholder":"Ex.: 3 mil em 6 meses"},
{"id":"msg","label":"Mensagens ou contatos por mês","placeholder":"Ex.: 100 contatos por mês"},
{"id":"vendas","label":"Vendas por mês","placeholder":"Ex.: 15 vendas por mês"},
{"id":"outra","label":"Outra meta","placeholder":"Ex.: 50 avaliações no Google"}],"secao":"Redes sociais, conteúdo e tom de voz"},
{"id":"tom_voz","tipo":"multipla","label":"Qual tom de voz a empresa quer usar?","ajuda":"Marque até 3.","opcoes":["Formal","Descontraído","Técnico","Educativo","Próximo e familiar","Institucional","Vendedor e direto"],"secao":"Redes sociais, conteúdo e tom de voz"},
{"id":"tom_obs","tipo":"longo","label":"Observações sobre o jeito de falar","ajuda":"Ex.: pode usar gíria; tratar o cliente por \"você\"; tratar por \"senhor\" quando for mais velho; nunca prometer o que não cumpre.","secao":"Redes sociais, conteúdo e tom de voz"},
